/**
 * Translate UI phrase by key with safe fallbacks
 */
export function translatePhrase(key: string, lang: LanguageCode): string {
  if (!key) return '';
  const phrase = UI_PHRASES?.[key];
  if (phrase) {
    if (phrase[lang]) {
      return phrase[lang]!;
    }
    if (phrase.en) {
      return phrase.en!;
    }
  }
  // Convert camelCase or snake_case key to human readable words if not found
  return key.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ').replace(/^./, (s) => s.toUpperCase()).trim();
}

const LOCALE_MAP: Record<LanguageCode, string> = {
  en: 'en-GB',
  hi: 'hi-IN',
  mr: 'mr-IN',
  ta: 'ta-IN',
  te: 'te-IN',
  kn: 'kn-IN',
  ml: 'ml-IN',
  bn: 'bn-IN',
  gu: 'gu-IN',
  pa: 'pa-IN',
  or: 'or-IN',
};

/**
 * Formats date and time into the localized representation for the selected language
 */
export function formatLocalizedDateTime(date: Date, lang: LanguageCode): string {
  try {
    const locale = LOCALE_MAP[lang] || 'en-GB';
    const dateStr = date.toLocaleDateString(locale, {
      weekday: 'short',
      day: 'numeric',
      month: 'short',
      year: 'numeric',
    });
    const timeStr = date.toLocaleTimeString(locale, {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
    });
    return `${dateStr} | ${timeStr}`;
  } catch (e) {
    return date.toLocaleString();
  }
}

