/**
 * Translate Soil Type by key (e.g. "alluvial", "black_cotton")
 */
export function translateSoilType(soil: string, lang: LanguageCode): string {
  if (!soil) return '';
  const key = soil.toLowerCase().replace(/\s+/g, '_').trim();
  if (SOIL_TYPES_MAP[key] && SOIL_TYPES_MAP[key][lang]) {
    return SOIL_TYPES_MAP[key][lang]!;
  }
  for (const [k, langMap] of Object.entries(SOIL_TYPES_MAP)) {
    if (key.includes(k) && langMap[lang]) {
      return langMap[lang]!;
    }
  }
  return soil;
}
